//! Metadata for route-backed page components.

use super::from_request::{ExtractError, RouteContext};
use super::loader::RouteLoaderId;
use super::navigation_guard::NavigationGuardId;
use reinhardt_core::page::Outlet;

/// Compile-time metadata exposed by props types generated by `#[component]`.
pub trait ComponentInfo {
	/// Returns the client route pattern.
	fn path() -> &'static str;

	/// Returns the route name used for reverse lookup.
	fn name() -> &'static str;

	/// Returns the PascalCase component name used by `page!` brace form.
	fn component_name() -> &'static str;

	/// Returns the snake_case render function name.
	fn function_name() -> &'static str;

	/// Returns the generated props type name.
	fn props_type_name() -> &'static str;

	/// Returns the optional route-level loader identifier.
	fn loader_id() -> Option<RouteLoaderId> {
		None
	}

	/// Returns the optional route-level navigation guard identifier.
	fn navigation_guard_id() -> Option<NavigationGuardId> {
		None
	}
}

/// Compile-time metadata exposed by props types generated by `#[layout]`.
pub trait LayoutInfo {
	/// Returns the client layout route pattern.
	fn path() -> &'static str;

	/// Returns the layout route name used for diagnostics.
	fn name() -> &'static str;

	/// Returns the PascalCase component name used by `page!` brace form.
	fn component_name() -> &'static str;

	/// Returns the snake_case render function name.
	fn function_name() -> &'static str;

	/// Returns the generated props type name.
	fn props_type_name() -> &'static str;

	/// Returns the optional route-level loader identifier.
	fn loader_id() -> Option<RouteLoaderId> {
		None
	}

	/// Returns the optional route-level navigation guard identifier.
	fn navigation_guard_id() -> Option<NavigationGuardId> {
		None
	}
}

/// Builds layout props from route context and router-managed outlet content.
pub trait FromLayoutRequest: Sized {
	/// Construct `Self` from the request context and the matched child outlet.
	///
	/// # Errors
	///
	/// Returns [`ExtractError`] when a required path or query parameter is
	/// missing or fails to parse.
	fn from_layout_request(ctx: &RouteContext, outlet: Outlet) -> Result<Self, ExtractError>;
}

/// Static metadata submitted by `#[component]` for diagnostics and tooling.
pub struct ComponentMetadata {
	/// Client route pattern.
	pub path: &'static str,
	/// Route name used by `ClientRouter`.
	pub name: &'static str,
	/// PascalCase component name.
	pub component_name: &'static str,
	/// Render function name.
	pub function_name: &'static str,
	/// Generated props type name.
	pub props_type_name: &'static str,
	/// Rust module path containing the component declaration.
	pub module_path: &'static str,
	/// Optional stable route-level loader identifier.
	pub loader_id: Option<RouteLoaderId>,
}

inventory::collect!(ComponentMetadata);

/// Static navigation-guard metadata submitted by `#[component]`.
pub struct ComponentNavigationGuardMetadata {
	/// Client route pattern.
	pub path: &'static str,
	/// Route name used by `ClientRouter`.
	pub name: &'static str,
	/// Stable route-level navigation guard identifier.
	pub navigation_guard_id: NavigationGuardId,
}

inventory::collect!(ComponentNavigationGuardMetadata);

/// Static metadata submitted by `#[layout]` for diagnostics and tooling.
pub struct LayoutMetadata {
	/// Client layout route pattern.
	pub path: &'static str,
	/// Layout route name used by `ClientRouter`.
	pub name: &'static str,
	/// PascalCase component name.
	pub component_name: &'static str,
	/// Render function name.
	pub function_name: &'static str,
	/// Generated props type name.
	pub props_type_name: &'static str,
	/// Rust module path containing the layout declaration.
	pub module_path: &'static str,
	/// Optional stable route-level loader identifier.
	pub loader_id: Option<RouteLoaderId>,
}

inventory::collect!(LayoutMetadata);

/// Static navigation-guard metadata submitted by `#[layout]`.
pub struct LayoutNavigationGuardMetadata {
	/// Client layout route pattern.
	pub path: &'static str,
	/// Layout route name used by `ClientRouter`.
	pub name: &'static str,
	/// Stable route-level navigation guard identifier.
	pub navigation_guard_id: NavigationGuardId,
}

inventory::collect!(LayoutNavigationGuardMetadata);

#[cfg(test)]
mod tests {
	use super::{ComponentMetadata, LayoutMetadata};

	#[test]
	fn legacy_metadata_struct_literals_remain_compatible() {
		let component = ComponentMetadata {
			path: "/component/",
			name: "component",
			component_name: "Component",
			function_name: "component",
			props_type_name: "ComponentProps",
			module_path: "tests",
			loader_id: None,
		};
		let layout = LayoutMetadata {
			path: "/layout/",
			name: "layout",
			component_name: "Layout",
			function_name: "layout",
			props_type_name: "LayoutProps",
			module_path: "tests",
			loader_id: None,
		};

		assert_eq!(component.path, "/component/");
		assert_eq!(layout.path, "/layout/");
	}
}
